def double_all(values):
    for i in range(len(values)):
        values[i] = values[i] * 2

marks = [3, 5, 8]
double_all(marks)
print(marks)

def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

print(safe_divide(10, 4))
print(safe_divide(10, 0))

